-- =============================================================================
-- HAND-WRITTEN: constraints, and the signature / note records that cannot be edited
-- =============================================================================
-- The AccountRole enum is stored under its @map names (provider_chiro, …).

ALTER TABLE "VisitNote" ADD CONSTRAINT "VisitNote_duration_sane"
  CHECK ("durationMin" IS NULL OR ("kind" = 'GENERAL' AND "durationMin" BETWEEN 1 AND 1440));

ALTER TABLE "DocumentationDraft" ADD CONSTRAINT "DocumentationDraft_sane"
  CHECK ("version" >= 1
     AND ("durationMin" IS NULL OR "durationMin" BETWEEN 1 AND 1440)
     AND "createdByRole" IN ('provider_chiro', 'provider_np', 'provider_nurse')
     AND char_length("subjective") <= 20000 AND char_length("objective") <= 20000
     AND char_length("assessment") <= 20000 AND char_length("plan") <= 20000 AND char_length("notes") <= 20000);

ALTER TABLE "NoteSignature" ADD CONSTRAINT "NoteSignature_sane"
  CHECK ("signedRole" IN ('provider_chiro', 'provider_np', 'provider_nurse')
     AND array_length("noteIds", 1) BETWEEN 1 AND 4
     AND ("aiAssisted" OR ("scribeSessionId" IS NULL AND "aiDraftUnchanged" IS NULL)));

ALTER TABLE "ScribeSession" ADD CONSTRAINT "ScribeSession_sane"
  CHECK ("startedRole" IN ('provider_chiro', 'provider_np', 'provider_nurse')
     AND ("audioBytes" IS NULL OR "audioBytes" >= 0));

-- A personal set belongs to exactly one account and an account has one; a shared set has no owner.
ALTER TABLE "MacroSet" ADD CONSTRAINT "MacroSet_owner_matches_scope"
  CHECK (("scope" = 'PERSONAL') = ("ownerAccountId" IS NOT NULL));
CREATE UNIQUE INDEX "MacroSet_one_personal_per_owner" ON "MacroSet" ("ownerAccountId") WHERE "scope" = 'PERSONAL';
ALTER TABLE "Macro" ADD CONSTRAINT "Macro_sane"
  CHECK (char_length("title") BETWEEN 1 AND 80 AND char_length("body") BETWEEN 1 AND 4000);

-- A signature is a record of who signed what and when: it is never edited or removed. Neither is a
-- clinical note — an error is corrected by an AMENDMENT (a new row pointing at the one it replaces),
-- which is the model the application already followed; this makes the database enforce it too.
-- (nw_reject_ledger_mutation() was created with the credit ledger.)
CREATE TRIGGER "NoteSignature_no_update_delete" BEFORE UPDATE OR DELETE ON "NoteSignature" FOR EACH ROW       EXECUTE FUNCTION nw_reject_ledger_mutation();
CREATE TRIGGER "NoteSignature_no_truncate"      BEFORE TRUNCATE         ON "NoteSignature" FOR EACH STATEMENT EXECUTE FUNCTION nw_reject_ledger_mutation();
CREATE TRIGGER "VisitNote_no_update_delete"     BEFORE UPDATE OR DELETE ON "VisitNote"     FOR EACH ROW       EXECUTE FUNCTION nw_reject_ledger_mutation();
CREATE TRIGGER "VisitNote_no_truncate"          BEFORE TRUNCATE         ON "VisitNote"     FOR EACH STATEMENT EXECUTE FUNCTION nw_reject_ledger_mutation();
